for (let r = 2; r <= 6; r++) {
  const c = wb.getRange(`E${r}`);
  c.setValue(`=AGGREGATE(16,6,$B${r}:$B$12/(($C${r}:$C$12>=0)*($C${r}:$C$12<=0.01)),0.5)`);
  const st = c.getStyle();
  st.setNumberFormat('0');
  st.setAlignment({ horizontal: 'left' });
  const b = st.getBorders();
  const stroke = { style: 'thin', color: '#000000' };
  b.setLeft(stroke); b.setRight(stroke); b.setTop(stroke); b.setBottom(stroke);
}
const out = [];
for (let r = 2; r <= 6; r++) {
  const c = wb.getRange(`E${r}`).getCell();
  const st = c.getStyle();
  out.push([r, c.getFormula?.(), c.getValue(), c.getText(), st.getNumberFormat(), JSON.stringify(st.getAlignment().toJSON?.()), JSON.stringify(st.getBorders().toJSON())]);
}
log(out); log(wb.getRange('E1:E7'));

